import os
from pathlib import Path


def test_data_files_generated():
    """Verify core data files are present after pipeline execution."""
    # Database generated by data_pipeline
    assert os.path.exists('data/instamart.db'), "Missing data/instamart.db"
    # Customer segments produced by RFM clustering
    assert os.path.exists('outputs/customer_segments.csv'), "Missing outputs/customer_segments.csv"
    # Triaging results
    assert os.path.exists('outputs/triage_results.csv'), "Missing outputs/triage_results.csv"
    # Agent run logs for ReAct scenarios
    assert os.path.exists('outputs/agent_runs.jsonl'), "Missing outputs/agent_runs.jsonl"
